24	// handleJobsChanged takes the router's snapshot. It is the only writer of the
25	// two fields.
26	func (m Model) handleJobsChanged(msg jobs.ChangedMsg) (tea.Model, tea.Cmd) {
27		m.jobs = msg.Runs
28		m.jobFrame = msg.Frame
29		// The footer's spinner is deliberately not touched: here it belongs to
30		// *loading* — a tab reading its list — and this view's scan progress is on
31		// the rows, not in the footer. Two writers of one field would fight every
32		// frame a scan and a load overlapped.
33		m.updateImageTable()
34		if m.registryBrowser != nil {
35			m.registryBrowser.SetTagScanningSet(m.scanningNames())
36		}
37		return m, nil
38	}
