40	// scanRun builds the run behind S, A, ctrl+a and a direct scan from the browser.
41	func (m Model) scanRun(names []string) jobs.Run {
42		run := jobs.NewRun(jobs.KindScan, command.ViewOCIResources, "", "images", names...)
43		// The alias is applied here rather than by whoever shows the run: it is
44		// this view's configuration that defines it, and `:jobs` has no business
45		// reading a registry list to print a name.
46		aliases := registryalias.From(m.registries)
47		for _, name := range names {
48			if display := docker.ApplyAliases(name, aliases); display != name {
49				run = run.WithDisplay(name, display)
50			}
51		}
52		return run
53	}
