55	// scanningImage reports whether an image is queued or being scanned, whoever
56	// started it.
57	func (m Model) scanningImage(name string) bool {
58		for _, run := range jobs.Unfinished(m.jobs) {
59			if run.Kind != jobs.KindScan {
60				continue
61			}
62			for _, item := range run.Items {
63				if item.Target == name && !item.State.Terminal() {
64					return true
65				}
66			}
67		}
68		return false
69	}
