71	// scanningNames lists every image with a scan in flight, for the registry
72	// browser, which decorates its tag rows from the same source.
73	func (m Model) scanningNames() map[string]bool {
74		out := make(map[string]bool)
75		for _, run := range jobs.Unfinished(m.jobs) {
76			if run.Kind != jobs.KindScan {
77				continue
78			}
79			for _, item := range run.Items {
80				if !item.State.Terminal() {
81					out[item.Target] = true
82				}
83			}
84		}
85		return out
86	}
