102	func (m Model) scanAllUnscanned() (tea.Model, tea.Cmd) {
103		if m.anyScanRunning() {
104			return m, nil
105		}
106		var queue []imageScanJob
107		for _, img := range m.images {
108			if img.Repository == "<none>" {
109				continue
110			}
111			name := img.Name()
112			if _, ok := m.scanCache[name]; !ok {
113				queue = append(queue, imageScanJob{Name: name, Target: img.ScanTarget()})
114			}
115		}
116		if len(queue) == 0 {
117			return m, m.footer.Warn("All images are already scanned")
