9	// filterStops returns the values `r` cycles through: every group that produced
10	// results, then every individual registry, then off. The group level is what
11	// makes "everything from this Nexus" one keystroke rather than eight.
12	func (b *RegistryBrowser) filterStops() []resultFilter {
13		seenGroup, seenEntry := map[string]bool{}, map[string]bool{}
14		var groups, singles []resultFilter
15		for _, t := range b.tags {
16			entry := b.entryFor(t.EntryKey)
17			if entry != nil && entry.ParentSlug != "" && !seenGroup[entry.ParentSlug] {
18				seenGroup[entry.ParentSlug] = true
19				groups = append(groups, resultFilter{groupSlug: entry.ParentSlug})
20			}
21			if !seenEntry[t.EntryKey] {
22				seenEntry[t.EntryKey] = true
23				singles = append(singles, resultFilter{entryKey: t.EntryKey})
24			}
25		}
26		// A single source has nothing to filter down to.
27		if len(singles) <= 1 {
28			return nil
29		}
30		// A group with every result under it says the same thing as "off".
31		if len(groups) == 1 && len(groups) == len(seenGroup) && len(singles) == countMembers(b.entries, groups[0].groupSlug) {
32			groups = nil
33		}
34		return append(groups, singles...)
35	}
36	
37	// countMembers returns how many entries belong to a group.
38	func countMembers(entries []browserRegistryEntry, slug string) int {
39		n := 0
40		for _, e := range entries {
41			if e.ParentSlug == slug {
42				n++
43			}
44		}
45		return n
46	}
