48	func (b *RegistryBrowser) cycleRegistryFilter() {
49		stops := b.filterStops()
50		if len(stops) == 0 {
51			b.registryFilter = resultFilter{}
52			b.rebuildTagTable()
53			return
54		}
55		if b.registryFilter.isEmpty() {
56			b.registryFilter = stops[0]
57			b.rebuildTagTable()
58			return
59		}
60		for i, s := range stops {
61			if s == b.registryFilter {
62				if i+1 < len(stops) {
63					b.registryFilter = stops[i+1]
64				} else {
65					b.registryFilter = resultFilter{} // back to everything
66				}
67				b.rebuildTagTable()
68				return
69			}
70		}
71		b.registryFilter = resultFilter{}
72		b.rebuildTagTable()
73	}
