75	// entryFor returns the browser entry a result came from, or nil.
76	//
77	// It resolves by entry key, not by URL: every member of a path-routed group
78	// answers to the same host, so a URL identifies a whole instance and a result
79	// would be unattributable (§3.18, and D40 one screen along).
80	func (b *RegistryBrowser) entryFor(key string) *browserRegistryEntry {
81		for i := range b.entries {
82			if b.entries[i].key == key {
83				return &b.entries[i]
84			}
85		}
86		return nil
87	}
