89	// registryFilterLabel returns a short display label for the active filter.
90	//
91	// D14: it used to search only the configured top-level entries, so filtering to
92	// a discovered member fell through to the synthesised URL — the one row in the
93	// view showing a URL where every other showed an alias. Members are entries now,
94	// so they resolve like anything else.
95	func (b *RegistryBrowser) registryFilterLabel() string {
96		if b.registryFilter.groupSlug != "" {
97			for _, reg := range b.registries {
98				if reg.Slug == b.registryFilter.groupSlug {
99					return browserAlias(reg)
100				}
101			}
102			return b.registryFilter.groupSlug
103		}
104		if entry := b.entryFor(b.registryFilter.entryKey); entry != nil {
105			if entry.ParentAlias != "" {
106				return entry.ParentAlias + "/" + entry.Alias
107			}
108			if entry.Alias != "" {
109				return entry.Alias
110			}
111			return registryRef(entry.URL, entry.repoPrefix)
112		}
113		return b.registryFilter.entryKey
114	}
