174	// registryHost strips the scheme from a configured registry URL, leaving what
175	// Docker itself is keyed on: `host[:port]`, plus whatever path a repository
176	// manager serves the registry under.
177	//
178	// A registry URL is written either way in practice — the form does not
179	// normalize it, `registryAPIURL` explicitly accepts both, and this package's own
180	// examples write `https://nexus.example.com/repository/docker-group`. Every
181	// Docker-facing use has to strip it, and none of the three that needed to did
182	// (D39): a `docker pull` reference carrying `https://` is not a reference at
183	// all, and a hub alias compared against a scheme-bearing string never matched,
184	// so images from a Hub configured as `https://docker.io` lost their `library/`
185	// prefix.
186	func registryHost(registryURL string) string {
187		base := strings.TrimSuffix(strings.TrimSpace(registryURL), "/")
188		for _, scheme := range []string{"https://", "http://"} {
189			if len(base) >= len(scheme) && strings.EqualFold(base[:len(scheme)], scheme) {
190				return base[len(scheme):]
191			}
192		}
193		return base
194	}
