196	// isDockerHub reports whether a registry URL names Docker Hub, under either of
197	// the two spellings and with or without a scheme. Hub is the one registry whose
198	// references carry no host, so every caller has to recognise it.
199	func isDockerHub(registryURL string) bool {
200		host := registryHost(registryURL)
201		return strings.EqualFold(host, "docker.io") || strings.EqualFold(host, "registry-1.docker.io")
202	}
