91	// scanOneImageCmd scans a single image, using a semaphore to limit concurrency.
92	// It emits ImageScanStartingMsg before scanning and ImageScanFinishedMsg after.
93	func scanOneImageCmd(job imageScanJob, opts scan.ScanOptions, sem chan struct{}) tea.Cmd {
94		// The context the scan runs under, so `K` can stop it (D7). It travels on
95		// the starting message, which is the same Update that marks the item
96		// running — two steps would leave a window where the row is running and
97		// cannot be stopped.
98		ctx, cancel := context.WithCancel(context.Background())
99	
100		return tea.Sequence(
101			// The starting message waits for its turn in the pool, which is what
102			// makes queued and running mean different things (D6). Emitted before
103			// the wait — as it was — every image in a batch reported itself running
104			// the instant the batch was dispatched, so twelve rows spun on four
105			// workers.
106			func() tea.Msg {
107				sem <- struct{}{}
108				return ImageScanStartingMsg{ImageName: job.Name, Cancel: cancel}
109			},
110			func() tea.Msg {
111				defer func() { <-sem }()
112				// Releases the context whether the scan was cancelled or ran to the
113				// end; the registry drops its copy when the item settles.
114				defer cancel()
115	
116				scanner := scan.NewScanner(opts)
117				result, err := scanner.Scan(ctx, job.Target, scan.TargetImage)
118				if err != nil {
119					log.Printf("ERROR: Scan failed for %s: %v", job.Name, err)
120					return ImageScanFinishedMsg{ImageName: job.Name, Err: err}
121				}
122	
123				// Scan() never returns a non-nil error; scanner errors land in result.Errors.
124				// If every scanner failed (errors present, no findings), surface it as an error.
125				if len(result.Errors) > 0 && result.TotalFindings() == 0 {
126					combined := strings.Join(result.Errors, "; ")
127					log.Printf("ERROR: Scan errors for %s: %s", job.Name, combined)
128					return ImageScanFinishedMsg{ImageName: job.Name, Err: fmt.Errorf("%s", combined)}
129				}
130	
131				entry := cache.ImageScanEntry{
132					Critical: result.Counts.Critical,
133					High:     result.Counts.High,
134					Medium:   result.Counts.Medium,
135					Low:      result.Counts.Low,
136					// Trivy lit les couches d'une image, ce que Gitleaks ne sait pas
137					// faire : c'est ce qui donne une étape secrets à un scan d'image,
138					// et donc un verdict à enregistrer.
139					Sensitive: result.SecretVerdict(),
140					ScannedAt: result.EndTime,
141				}
142				scanCache, cErr := cache.NewImageScanCache()
143				if cErr != nil {
144					log.Printf("ERROR: Failed to open scan cache: %v", cErr)
145				} else if sErr := scanCache.Set(job.Name, entry); sErr != nil {
146					log.Printf("ERROR: Failed to cache scan for %s: %v", job.Name, sErr)
147				}
148				// Rule 126: persist full result so Enter can load it without re-scanning
149				if sErr := cache.SaveImageScanResult(job.Name, result); sErr != nil {
150					log.Printf("ERROR: Failed to save full scan result for %s: %v", job.Name, sErr)
151				}
152				return ImageScanFinishedMsg{ImageName: job.Name, Entry: entry}
153			},
154		)
155	}
