124	// Msgs executes cmd and returns every message it produced, flattening the
125	// tea.Batch and tea.Sequence trees. A nil command, or one returning nil, yields
126	// no messages.
127	//
128	// The command runs synchronously on the calling goroutine. Do not pass a command
129	// that sleeps or performs I/O — tea.Tick blocks for its whole duration, and the
130	// Docker runners shell out. Assert on the command's identity or on model state
131	// instead for those.
132	func Msgs(cmd tea.Cmd) []tea.Msg {
133		if cmd == nil {
134			return nil
135		}
136		msg := cmd()
137		if msg == nil {
138			return nil
139		}
140		if batch, ok := msg.(tea.BatchMsg); ok {
141			var out []tea.Msg
142			for _, c := range batch {
143				out = append(out, Msgs(c)...)
144			}
145			return out
