// cliRunner is the production dockerRunner: it shells out to the real binary.
type cliRunner struct{}

func (cliRunner) LookPath() error {
	_, err := exec.LookPath("docker")
	return err
}

func (cliRunner) Build(args ...string) *exec.Cmd {
	return exec.Command("docker", args...)
}

func (cliRunner) Run(dc dockerCmd) ([]byte, error) {
	name := "docker"
	if dc.Helper != "" {
		name = "docker-credential-" + dc.Helper
	}
	cmd := exec.Command(name, dc.Args...) //nolint:gosec // helper name comes from ~/.docker/config.json
	if dc.Stdin != "" {
		cmd.Stdin = strings.NewReader(dc.Stdin)
	}
	if dc.Combined {
		return cmd.CombinedOutput()
	}
	return cmd.Output()
}

// runner is swapped by tests via stubRunner. Production code never reassigns
// it, so the package stays safe to call concurrently; tests that swap it must
// not run in parallel.
var runner dockerRunner = cliRunner{}

// requireDocker reports the absence of the docker binary with the error message
// callers have always produced.
func requireDocker() error {
	if err := runner.LookPath(); err != nil {
		return fmt.Errorf("docker not found: %w", err)
	}
	return nil
}

// dockerOutput runs `docker args...` and returns stdout only.
func dockerOutput(args ...string) ([]byte, error) {
	return runner.Run(dockerCmd{Args: args})
}

// dockerCombined runs `docker args...` and returns stdout and stderr merged.
func dockerCombined(args ...string) ([]byte, error) {
	return runner.Run(dockerCmd{Args: args, Combined: true})
}

// wrapErr reports a failed invocation whose stderr was not captured, keeping the
// underlying error for errors.Is/As.
func wrapErr(label string, err error) error {
	return fmt.Errorf("%s failed: %w", label, err)
}

// errWithOutput reports a failed invocation using the captured output, which
// carries Docker's own diagnostic.
func errWithOutput(label string, output []byte) error {
	return fmt.Errorf("%s failed: %s", label, strings.TrimSpace(string(output)))
}

// mutate runs a docker subcommand whose output only matters on failure, and
// wraps that output in an error prefixed with label (e.g. "docker stop failed").
func mutate(label string, args ...string) error {
	output, err := dockerCombined(args...)
	if err != nil {
		return fmt.Errorf("%s failed: %s", label, strings.TrimSpace(string(output)))
	}
	return nil
}

// prune runs a docker prune subcommand and returns its trimmed report.
func prune(label string, args ...string) (string, error) {
	output, err := dockerCombined(args...)
	if err != nil {
		return "", fmt.Errorf("%s failed: %s", label, strings.TrimSpace(string(output)))
	}
	return strings.TrimSpace(string(output)), nil

package jobsview

import (
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
)

// The reasons a key is refused, as named constants: the header reads them to
// grey, the handler reads them to refuse, and a test reads them to check the
// two agree (Rule 130).
const (
	reasonNoRun         = "No run selected"
	reasonNoTarget      = "No target selected"
	reasonEmptyRun      = "This run has no targets"
	reasonInsideRun     = "Already inside a run"
	reasonTopLevel      = "Already at the top level"
	reasonItemsUnsorted = "Targets keep the order they were dispatched in"
	reasonRunSettled    = "This run has already finished"
	reasonTargetSettled = "This target has already finished"
)

// stopRefusal names why a run cannot be stopped, in the run's own words.
//
// The wording is per kind because the reason is: a delete in flight must never
// be cut, and saying so with the verb the row already shows is what makes the
// greyed key readable without opening the help.
func stopRefusal(kind jobs.Kind) string {
	return "A " + string(kind) + " cannot be stopped once it has started"
}

// availability is what the selected row and the current level permit, computed
// once and read by both halves of the view.
//
// One field per key rather than a bool and a string apart: an empty reason
// means available, so the two cannot disagree.
type availability struct {
	Open  shortcut.Availability
	Close shortcut.Availability
	Sort  shortcut.Availability
	Stop  shortcut.Availability
}

// availability answers for the level, and inside it for the selected row.
//
// The list is the same three entries at both levels, and only the greying
// changes (Rule 130): a shortcut column that reorganised itself every time the
// reader pressed → would be unreadable exactly when they are moving around.
func (m Model) availability() availability {
	var a availability

	if m.level == levelItems {
		// The drill is one level deep by construction — there is nothing under
		// a target — so → has nowhere left to go, and `.` has no column to
		// cycle because the item table opens unsorted on purpose (see New).
		a.Open = shortcut.Unavailable(reasonInsideRun)
		a.Sort = shortcut.Unavailable(reasonItemsUnsorted)
		a.Stop = m.itemStoppable()
		return a
	}

